//! Nix Binary Cache server.
//!
//! This module implements the Nix Binary Cache API.
//!
//! The implementation is based on the specifications at <https://github.com/fzakaria/nix-http-binary-cache-api-spec>.

use std::collections::VecDeque;
use std::io::{Error as IoError, ErrorKind as IoErrorKind};
use std::path::PathBuf;
use std::sync::Arc;

use axum::{
    body::StreamBody,
    extract::{Extension, Path},
    http::StatusCode,
    response::{IntoResponse, Redirect, Response},
    routing::get,
    Router,
};
use futures::stream::BoxStream;
use serde::Serialize;
use tokio_util::io::ReaderStream;
use tracing::instrument;

use crate::database::entity::chunk::ChunkModel;
use crate::database::AtticDatabase;
use crate::error::{ErrorKind, ServerResult};
use crate::narinfo::NarInfo;
use crate::nix_manifest;
use crate::storage::{Download, StorageBackend};
use crate::{RequestState, State};
use attic::cache::CacheName;
use attic::mime;
use attic::nix_store::StorePathHash;
use attic::stream::merge_chunks;

/// Nix cache information.
///
/// An example of a correct response is as follows:
///
/// ```text
/// StoreDir: /nix/store
/// WantMassQuery: 1
/// Priority: 40
/// ```
#[derive(Debug, Clone, Serialize)]
struct NixCacheInfo {
    /// Whether this binary cache supports bulk queries.
    #[serde(rename = "WantMassQuery")]
    want_mass_query: bool,

    /// The Nix store path this binary cache uses.
    #[serde(rename = "StoreDir")]
    store_dir: PathBuf,

    /// The priority of the binary cache.
    ///
    /// A lower number denotes a higher priority.
    /// <https://cache.nixos.org> has a priority of 40.
    #[serde(rename = "Priority")]
    priority: i32,
}

impl IntoResponse for NixCacheInfo {
    fn into_response(self) -> Response {
        match nix_manifest::to_string(&self) {
            Ok(body) => Response::builder()
                .status(StatusCode::OK)
                .header("Content-Type", mime::NIX_CACHE_INFO)
                .body(body)
                .unwrap()
                .into_response(),
            Err(e) => e.into_response(),
        }
    }
}

/// Gets information on a cache.
#[instrument(skip_all, fields(cache_name))]
async fn get_nix_cache_info(
    Extension(state): Extension<State>,
    Extension(req_state): Extension<RequestState>,
    Path(cache_name): Path<CacheName>,
) -> ServerResult<NixCacheInfo> {
    let database = state.database().await?;
    let cache = req_state
        .auth
        .auth_cache(database, &cache_name, |cache, permission| {
            permission.require_pull()?;
            Ok(cache)
        })
        .await?;

    req_state.set_public_cache(cache.is_public);

    let info = NixCacheInfo {
        want_mass_query: true,
        store_dir: cache.store_dir.into(),
        priority: cache.priority,
    };

    Ok(info)
}

/// Gets various information on a store path hash.
///
/// `/:cache/:path`, which may be one of
/// - GET `/:cache/{storePathHash}.narinfo`
/// - HEAD `/:cache/{storePathHash}.narinfo`
/// - GET `/:cache/{storePathHash}.ls` (not implemented)
#[instrument(skip_all, fields(cache_name, path))]
#[axum_macros::debug_handler]
async fn get_store_path_info(
    Extension(state): Extension<State>,
    Extension(req_state): Extension<RequestState>,
    Path((cache_name, path)): Path<(CacheName, String)>,
) -> ServerResult<NarInfo> {
    let components: Vec<&str> = path.splitn(2, '.').collect();

    if components.len() != 2 {
        return Err(ErrorKind::NotFound.into());
    }

    // TODO: Other endpoints
    if components[1] != "narinfo" {
        return Err(ErrorKind::NotFound.into());
    }

    let store_path_hash = StorePathHash::new(components[0].to_string())?;

    tracing::debug!(
        "Received request for {}.narinfo in {:?}",
        store_path_hash.as_str(),
        cache_name
    );

    let (object, cache, nar, _) = state
        .database()
        .await?
        .find_object_and_chunks_by_store_path_hash(&cache_name, &store_path_hash, false)
        .await?;

    let permission = req_state
        .auth
        .get_permission_for_cache(&cache_name, cache.is_public);
    permission.require_pull()?;

    req_state.set_public_cache(cache.is_public);

    let mut narinfo = object.to_nar_info(&nar)?;

    if narinfo.signature().is_none() {
        let keypair = cache.keypair()?;
        narinfo.sign(&keypair);
    }

    Ok(narinfo)
}

/// Gets a NAR.
///
/// - GET `:cache/nar/{storePathHash}.nar`
///
/// Here we use the store path hash not the NAR hash or file hash
/// for better logging. In reality, the files are deduplicated by
/// content-addressing.
#[instrument(skip_all, fields(cache_name, path))]
async fn get_nar(
    Extension(state): Extension<State>,
    Extension(req_state): Extension<RequestState>,
    Path((cache_name, path)): Path<(CacheName, String)>,
) -> ServerResult<Response> {
    let components: Vec<&str> = path.splitn(2, '.').collect();

    if components.len() != 2 {
        return Err(ErrorKind::NotFound.into());
    }

    if components[1] != "nar" {
        return Err(ErrorKind::NotFound.into());
    }

    let store_path_hash = StorePathHash::new(components[0].to_string())?;

    tracing::debug!(
        "Received request for {}.nar in {:?}",
        store_path_hash.as_str(),
        cache_name
    );

    let database = state.database().await?;

    let (object, cache, _nar, chunks) = database
        .find_object_and_chunks_by_store_path_hash(&cache_name, &store_path_hash, true)
        .await?;

    let permission = req_state
        .auth
        .get_permission_for_cache(&cache_name, cache.is_public);
    permission.require_pull()?;

    req_state.set_public_cache(cache.is_public);

    if chunks.iter().any(Option::is_none) {
        // at least one of the chunks is missing :(
        return Err(ErrorKind::IncompleteNar.into());
    }

    database.bump_object_last_accessed(object.id).await?;

    if chunks.len() == 1 {
        // single chunk
        let chunk = chunks[0].as_ref().unwrap();
        let remote_file = &chunk.remote_file.0;
        let storage = state.storage().await?;
        match storage.download_file_db(remote_file, false).await? {
            Download::Url(url) => Ok(Redirect::temporary(&url).into_response()),
            Download::Stream(stream) => {
                let body = StreamBody::new(stream);
                Ok(body.into_response())
            }
            Download::AsyncRead(stream) => {
                let stream = ReaderStream::new(stream);
                let body = StreamBody::new(stream);
                Ok(body.into_response())
            }
        }
    } else {
        // reassemble NAR
        fn io_error<E: std::error::Error + Send + Sync + 'static>(e: E) -> IoError {
            IoError::new(IoErrorKind::Other, e)
        }

        let streamer = |chunk: ChunkModel, storage: Arc<Box<dyn StorageBackend + 'static>>| async move {
            match storage
                .download_file_db(&chunk.remote_file.0, true)
                .await
                .map_err(io_error)?
            {
                Download::Url(_) => Err(IoError::new(
                    IoErrorKind::Other,
                    "URLs not supported for NAR reassembly",
                )),
                Download::Stream(stream) => Ok(stream),
                Download::AsyncRead(stream) => {
                    let stream: BoxStream<_> = Box::pin(ReaderStream::new(stream));
                    Ok(stream)
                }
            }
        };

        let chunks: VecDeque<_> = chunks.into_iter().map(Option::unwrap).collect();
        let storage = state.storage().await?.clone();

        // TODO: Make num_prefetch configurable
        // The ideal size depends on the average chunk size
        let merged = merge_chunks(chunks, streamer, storage, 2);
        let body = StreamBody::new(merged);
        Ok(body.into_response())
    }
}

pub fn get_router() -> Router {
    Router::new()
        .route("/:cache/nix-cache-info", get(get_nix_cache_info))
        .route("/:cache/:path", get(get_store_path_info))
        .route("/:cache/nar/:path", get(get_nar))
}

//! Nix Binary Cache server.
//!
//! This module contains Attic-specific extensions to the
//! Nix Binary Cache API.

/// Header indicating a cache's visibility.
pub const ATTIC_CACHE_VISIBILITY: &str = "X-Attic-Cache-Visibility";

//! Cache configuration endpoint.

use anyhow::anyhow;
use axum::extract::{Extension, Json, Path};
use chrono::Utc;
use sea_orm::sea_query::{Expr, OnConflict};
use sea_orm::ActiveValue::Set;
use sea_orm::{ColumnTrait, EntityTrait, QueryFilter};
use tracing::instrument;

use crate::database::entity::cache::{self, Entity as Cache};
use crate::database::entity::Json as DbJson;
use crate::error::{ErrorKind, ServerError, ServerResult};
use crate::{RequestState, State};
use attic::api::v1::cache_config::{
    CacheConfig, CreateCacheRequest, KeypairConfig, RetentionPeriodConfig,
};
use attic::cache::CacheName;
use attic::signing::NixKeypair;

#[instrument(skip_all, fields(cache_name))]
pub(crate) async fn get_cache_config(
    Extension(state): Extension<State>,
    Extension(req_state): Extension<RequestState>,
    Path(cache_name): Path<CacheName>,
) -> ServerResult<Json<CacheConfig>> {
    let database = state.database().await?;
    let cache = req_state
        .auth
        .auth_cache(database, &cache_name, |cache, permission| {
            permission.require_pull()?;
            Ok(cache)
        })
        .await?;

    let public_key = cache.keypair()?.export_public_key();

    let retention_period_config = if let Some(period) = cache.retention_period {
        RetentionPeriodConfig::Period(period as u32)
    } else {
        RetentionPeriodConfig::Global
    };

    Ok(Json(CacheConfig {
        substituter_endpoint: Some(req_state.substituter_endpoint(cache_name)?),
        api_endpoint: Some(req_state.api_endpoint()?),
        keypair: None,
        public_key: Some(public_key),
        is_public: Some(cache.is_public),
        store_dir: Some(cache.store_dir),
        priority: Some(cache.priority),
        upstream_cache_key_names: Some(cache.upstream_cache_key_names.0),
        retention_period: Some(retention_period_config),
    }))
}

#[instrument(skip_all, fields(cache_name, payload))]
pub(crate) async fn configure_cache(
    Extension(state): Extension<State>,
    Extension(req_state): Extension<RequestState>,
    Path(cache_name): Path<CacheName>,
    Json(payload): Json<CacheConfig>,
) -> ServerResult<()> {
    let database = state.database().await?;
    let (cache, permission) = req_state
        .auth
        .auth_cache(database, &cache_name, |cache, permission| {
            permission.require_configure_cache()?;
            Ok((cache, permission.clone()))
        })
        .await?;

    let mut update = cache::ActiveModel {
        id: Set(cache.id),
        ..Default::default()
    };

    let mut modified = false;

    if let Some(keypair_cfg) = payload.keypair {
        let keypair = match keypair_cfg {
            KeypairConfig::Generate => NixKeypair::generate(cache_name.as_str())?,
            KeypairConfig::Keypair(k) => k,
        };
        update.keypair = Set(keypair.export_keypair());
        modified = true;
    }

    if let Some(is_public) = payload.is_public {
        update.is_public = Set(is_public);
        modified = true;
    }

    if let Some(store_dir) = payload.store_dir {
        update.store_dir = Set(store_dir);
        modified = true;
    }

    if let Some(priority) = payload.priority {
        update.priority = Set(priority);
        modified = true;
    }

    if let Some(upstream_cache_key_names) = payload.upstream_cache_key_names {
        update.upstream_cache_key_names = Set(DbJson(upstream_cache_key_names));
        modified = true;
    }

    if let Some(retention_period_config) = payload.retention_period {
        permission.require_configure_cache_retention()?;

        match retention_period_config {
            RetentionPeriodConfig::Global => {
                update.retention_period = Set(None);
            }
            RetentionPeriodConfig::Period(period) => {
                update.retention_period =
                    Set(Some(period.try_into().map_err(|_| {
                        ErrorKind::RequestError(anyhow!("Invalid retention period"))
                    })?));
            }
        }

        modified = true;
    }

    if modified {
        Cache::update(update)
            .exec(database)
            .await
            .map_err(ServerError::database_error)?;

        Ok(())
    } else {
        Err(ErrorKind::RequestError(anyhow!("No modifiable fields were set.")).into())
    }
}

#[instrument(skip_all, fields(cache_name))]
pub(crate) async fn destroy_cache(
    Extension(state): Extension<State>,
    Extension(req_state): Extension<RequestState>,
    Path(cache_name): Path<CacheName>,
) -> ServerResult<()> {
    let database = state.database().await?;
    let cache = req_state
        .auth
        .auth_cache(database, &cache_name, |cache, permission| {
            permission.require_destroy_cache()?;
            Ok(cache)
        })
        .await?;

    if state.config.soft_delete_caches {
        // Perform soft deletion
        let deletion = Cache::update_many()
            .col_expr(cache::Column::DeletedAt, Expr::value(Some(Utc::now())))
            .filter(cache::Column::Id.eq(cache.id))
            .filter(cache::Column::DeletedAt.is_null())
            .exec(database)
            .await
            .map_err(ServerError::database_error)?;

        if deletion.rows_affected == 0 {
            // Someone raced to (soft) delete the cache before us
            Err(ErrorKind::NoSuchCache.into())
        } else {
            Ok(())
        }
    } else {
        // Perform hard deletion
        let deletion = Cache::delete_many()
            .filter(cache::Column::Id.eq(cache.id))
            .filter(cache::Column::DeletedAt.is_null()) // don't operate on soft-deleted caches
            .exec(database)
            .await
            .map_err(ServerError::database_error)?;

        if deletion.rows_affected == 0 {
            // Someone raced to (soft) delete the cache before us
            Err(ErrorKind::NoSuchCache.into())
        } else {
            Ok(())
        }
    }
}

#[instrument(skip_all, fields(cache_name, payload))]
pub(crate) async fn create_cache(
    Extension(state): Extension<State>,
    Extension(req_state): Extension<RequestState>,
    Path(cache_name): Path<CacheName>,
    Json(payload): Json<CreateCacheRequest>,
) -> ServerResult<()> {
    let permission = req_state.auth.get_permission_for_cache(&cache_name, false);
    permission.require_create_cache()?;

    let database = state.database().await?;

    let keypair = match payload.keypair {
        KeypairConfig::Generate => NixKeypair::generate(cache_name.as_str())?,
        KeypairConfig::Keypair(k) => k,
    };

    let num_inserted = Cache::insert(cache::ActiveModel {
        name: Set(cache_name.to_string()),
        keypair: Set(keypair.export_keypair()),
        is_public: Set(payload.is_public),
        store_dir: Set(payload.store_dir),
        priority: Set(payload.priority),
        upstream_cache_key_names: Set(DbJson(payload.upstream_cache_key_names)),
        created_at: Set(Utc::now()),
        ..Default::default()
    })
    .on_conflict(
        OnConflict::column(cache::Column::Name)
            .do_nothing()
            .to_owned(),
    )
    .exec_without_returning(database)
    .await
    .map_err(ServerError::database_error)?;

    if num_inserted == 0 {
        // The cache already exists
        Err(ErrorKind::CacheAlreadyExists.into())
    } else {
        Ok(())
    }
}

//! Cache configuration endpoint.

use serde::{Deserialize, Serialize};

use crate::signing::NixKeypair;

#[derive(Debug, Serialize, Deserialize)]
pub struct CreateCacheRequest {
    /// The keypair of the cache.
    pub keypair: KeypairConfig,

    /// Whether the cache is public or not.
    ///
    /// Anonymous clients are implicitly granted the "pull"
    /// permission to public caches.
    pub is_public: bool,

    /// The Nix store path this binary cache uses.
    ///
    /// This is usually `/nix/store`.
    pub store_dir: String,

    /// The priority of the binary cache.
    ///
    /// A lower number denotes a higher priority.
    /// <https://cache.nixos.org> has a priority of 40.
    pub priority: i32,

    /// A list of signing key names of upstream caches.
    ///
    /// The list serves as a hint to clients to avoid uploading
    /// store paths signed with such keys.
    pub upstream_cache_key_names: Vec<String>,
}

/// Configuration of a cache.
///
/// Specifying `None` means using the default value or
/// keeping the current value.
#[derive(Debug, Serialize, Deserialize)]
pub struct CacheConfig {
    /// The keypair of the cache.
    ///
    /// The keypair is never returned by the server, but can
    /// be configured by the client.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub keypair: Option<KeypairConfig>,

    /// The Nix binary cache endpoint of the cache.
    ///
    /// This is the endpoint that should be added to `nix.conf`.
    /// This is read-only and may not be available.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub substituter_endpoint: Option<String>,

    /// The Attic API endpoint.
    ///
    /// This is read-only and may not be available.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub api_endpoint: Option<String>,

    /// The public key of the cache, in the canonical format used by Nix.
    ///
    /// This is read-only and may not be available.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub public_key: Option<String>,

    /// Whether the cache is public or not.
    ///
    /// Anonymous clients are implicitly granted the "pull"
    /// permission to public caches.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub is_public: Option<bool>,

    /// The Nix store path this binary cache uses.
    ///
    /// This is usually `/nix/store`.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub store_dir: Option<String>,

    /// The priority of the binary cache.
    ///
    /// A lower number denotes a higher priority.
    /// <https://cache.nixos.org> has a priority of 40.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub priority: Option<i32>,

    /// A list of signing key names of upstream caches.
    ///
    /// The list serves as a hint to clients to avoid uploading
    /// store paths signed with such keys.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub upstream_cache_key_names: Option<Vec<String>>,

    /// The retention period of the cache.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub retention_period: Option<RetentionPeriodConfig>,
}

/// Configuaration of a keypair.
#[derive(Debug, Serialize, Deserialize)]
pub enum KeypairConfig {
    /// Use a randomly-generated keypair.
    Generate,

    /// Use a client-specified keypair.
    Keypair(NixKeypair),
}

/// Configuration of retention period.
#[derive(Debug, Serialize, Deserialize)]
pub enum RetentionPeriodConfig {
    /// Use the global default.
    Global,

    /// Specify a retention period in seconds.
    ///
    /// If 0, then time-based garbage collection is disabled.
    Period(u32),
}

impl CacheConfig {
    pub fn blank() -> Self {
        Self {
            keypair: None,
            substituter_endpoint: None,
            api_endpoint: None,
            public_key: None,
            is_public: None,
            store_dir: None,
            priority: None,
            upstream_cache_key_names: None,
            retention_period: None,
        }
    }
}

# Generates a script to bootstrap the Attic client with a substituter for
# CI usage. Will be simplier when Attic is in cache.nixos.org.

{ self
, writeText
, writeScript

, substituter ? "https://staging.attic.rs/attic-ci"
, trustedPublicKey ? "attic-ci:U5Sey4mUxwBXM3iFapmP0/ogODXywKLRNgRPQpEXxbo="
}:

let
  cacheNixosOrg = "https://cache.nixos.org";
  cacheNixosOrgKey = "cache.nixos.org-1:6NCHdD59X431o0gWypbMrAURkbJ16ZPMQFGspcDShjY=";

  bootstrapHeader = ''
    let
      maybeStorePath = if builtins ? langVersion && builtins.lessThan 1 builtins.langVersion
        then builtins.storePath
        else x: x;
      mkFakeDerivation = attrs: outputs:
        let
          outputNames = builtins.attrNames outputs;
          common = attrs // outputsSet //
            { type = "derivation";
              outputs = outputNames;
              all = outputsList;
            };
          outputToAttrListElement = outputName:
            { name = outputName;
              value = common // {
                inherit outputName;
                outPath = maybeStorePath (builtins.getAttr outputName outputs);
                drvPath = maybeStorePath (builtins.getAttr outputName outputs);
              };
            };
          outputsList = map outputToAttrListElement outputNames;
          outputsSet = builtins.listToAttrs outputsList;
        in outputsSet;
    in
  '';

  makeBootstrap = system: let
    package =
      if system == "x86_64-linux" then self.packages.${system}.attic-client-static
      else self.packages.${system}.attic-client;
  in ''
    "${system}" = (mkFakeDerivation {
      name = "${package.name}";
      system = "${system}";
    } {
      out = "${package.out}";
    }).out;
  '';

  bootstrapExpr = ''
    { system ? builtins.currentSystem }:
    ${bootstrapHeader}
    {
      ${makeBootstrap "x86_64-linux"}
      ${makeBootstrap "aarch64-linux"}
      ${makeBootstrap "x86_64-darwin"}
      ${makeBootstrap "aarch64-darwin"}
    }.''${system}
  '';

  bootstrapScript = writeScript "install-attic-ci.sh" ''
    #!/usr/bin/env bash
    set -euo pipefail
    expr=$(mktemp)

    cleanup() {
      rm -f "$expr"
    }

    cat >"$expr" <<'EOF'
      ${bootstrapExpr}
    EOF

    nix-env --substituters "${substituter} ${cacheNixosOrg}" --trusted-public-keys "${trustedPublicKey} ${cacheNixosOrgKey}" -if "$expr"
  '';
in bootstrapScript

use sea_orm_migration::prelude::*;

