//! get-missing-paths v1
//!
//! `POST /_api/v1/get-missing-paths`
//!
//! Requires "push" permission.

use serde::{Deserialize, Serialize};

use crate::cache::CacheName;
use crate::nix_store::StorePathHash;

#[derive(Debug, Serialize, Deserialize)]
pub struct GetMissingPathsRequest {
    /// The name of the cache.
    pub cache: CacheName,

    /// The list of store paths.
    pub store_path_hashes: Vec<StorePathHash>,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct GetMissingPathsResponse {
    /// A list of paths that are not in the cache.
    pub missing_paths: Vec<StorePathHash>,
}

mod cache_config;
mod get_missing_paths;
mod upload_path;

use axum::{
    routing::{delete, get, patch, post, put},
    Router,
};

pub(crate) fn get_router() -> Router {
    Router::new()
        .route(
            "/_api/v1/get-missing-paths",
            post(get_missing_paths::get_missing_paths),
        )
        .route("/_api/v1/upload-path", put(upload_path::upload_path))
        .route(
            "/:cache/attic-cache-info",
            get(cache_config::get_cache_config),
        )
        .route(
            "/_api/v1/cache-config/:cache",
            get(cache_config::get_cache_config),
        )
        .route(
            "/_api/v1/cache-config/:cache",
            post(cache_config::create_cache),
        )
        .route(
            "/_api/v1/cache-config/:cache",
            patch(cache_config::configure_cache),
        )
        .route(
            "/_api/v1/cache-config/:cache",
            delete(cache_config::destroy_cache),
        )
}
